from typing import List

def eventualSafeNodes(V: int, adj: List[List[int]]) -> List[int]:
    # Reverse the graph to find eventual safe nodes
    reverse_adj = [[] for _ in range(V)]
    out_degree = [0] * V

    for u in range(V):
        for v in adj[u]:
            reverse_adj[v].append(u)
            out_degree[u] += 1

    # Queue for nodes with zero out-degree in the reversed graph
    queue = [u for u in range(V) if out_degree[u] == 0]
    safe_nodes = set(queue)

    while queue:
        u = queue.pop()
        for v in reverse_adj[u]:
            out_degree[v] -= 1
            if out_degree[v] == 0:
                queue.append(v)
                safe_nodes.add(v)

    return sorted(safe_nodes)
